{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "The S3 bucket 'admin_dashboard' does not have versioning enabled, which can lead to data loss in case of accidental deletion or overwrite."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket 'admin_dashboard' lacks a Public Access block, potentially exposing it to unauthorized public access."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"admin_dashboard\" {\n  bucket = \"smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}\"\n}\n\nresource \"aws_s3_bucket_versioning\" \"admin_dashboard_versioning\" {\n  bucket = aws_s3_bucket.admin_dashboard.id\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"admin_dashboard_public_access_block\" {\n  bucket = aws_s3_bucket.admin_dashboard.id\n\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Enabled versioning for the S3 bucket 'admin_dashboard' and added a Public Access block to restrict public access."
}
